{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울시 조례상 자전거 주차장 우선 설치 장소에 버스정류장 주변 포함 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "서울시가 자전거 주차장을 우선 설치해야 할 장소에 버스정류장 주변은 포함됩니다. 서울특별시 자전거이용 활성화에 관한 조례 제7조제1항은 시장이 공원, 하천, 지하철역, 버스정류소, 공공청사 등 자전거 이용이 많거나 많을 것으로 예상되는 장소에 자전거주차장을 우선하여 설치하여야 한다고 정하고 있습니다.",
          "b_ids": "자전거:제7조제1항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
